import crypto from 'crypto';

/**
 * Hashes a password using scrypt.
 * Returns a string in the format: "salt:hash"
 */
export async function hashPassword(password: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const salt = crypto.randomBytes(16).toString('hex');
    crypto.scrypt(password, salt, 64, (err, derivedKey) => {
      if (err) reject(err);
      resolve(salt + ':' + derivedKey.toString('hex'));
    });
  });
}

/**
 * Verifies a password against a stored hash generated by hashPassword.
 */
export async function verifyPassword(password: string, hashString: string): Promise<boolean> {
  return new Promise((resolve, reject) => {
    const [salt, key] = hashString.split(':');
    if (!salt || !key) return resolve(false);

    crypto.scrypt(password, salt, 64, (err, derivedKey) => {
      if (err) reject(err);
      resolve(key === derivedKey.toString('hex'));
    });
  });
}

export function generateSessionToken(): string {
  return crypto.randomBytes(32).toString('hex');
}

import { NextRequest } from 'next/server';
import prisma from '@/lib/db/db';

export async function getUserFromRequest(req: NextRequest) {
  const sessionToken = req.cookies.get('admin-session')?.value;
  if (!sessionToken) return null;
  return await prisma.user.findUnique({ where: { sessionToken } });
}

